1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUMS: Record<string, number> = {
4	  sword: 100,
5	};
6	
7	const COMPONENT_BASE_PREMIUM = 25;
8	const COMPONENT_BLOCK_SIZE = 3;
9	const COMPONENT_BLOCK_PREMIUM = 60;
10	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
11	
12	const FIRST_INSURANCE_SURCHARGE = 0.1;
13	const CURSE_SURCHARGE = 0.5;
14	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
15	const HIGH_ENCHANTMENT_THRESHOLD = 5;
16	const LOYALTY_DISCOUNT = 0.2;
17	const LOYALTY_YEARS_THRESHOLD = 2;
18	
19	interface Item {
20	  type: string;
21	  cursed?: boolean;
22	  enchantment?: number;
23	}
24	
25	interface QuoteStep {
26	  op: "quote";
27	  items: Item[];
28	}
29	
30	interface Customer {
31	  yearsWithMHPCO: number;
32	}
33	
34	interface Scenario {
35	  customer: Customer;
36	  steps: QuoteStep[];
37	}
38	
39	interface QuoteResult {
40	  premium: number;
41	}
42	
43	interface ScenarioResult {
44	  results: QuoteResult[];
45	}
46	
47	const componentGroupBase = (count: number): number =>
48	  count === COMPONENT_BLOCK_SIZE
49	    ? COMPONENT_BLOCK_PREMIUM
50	    : count * COMPONENT_BASE_PREMIUM;
51	
52	const countByType = (items: Item[]): Map<string, number> => {
53	  const counts = new Map<string, number>();
54	  for (const item of items) {
55	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
56	  }
57	  return counts;
58	};
59	
60	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
61	
62	const isHighEnchantment = (item: Item): boolean =>
63	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
64	
65	interface PricedUnit {
66	  base: number;
67	  surcharges: number[];
68	}
69	
70	const mainItemUnit = (item: Item): PricedUnit => {
71	  const base = BASE_PREMIUMS[item.type];
72	  const surcharges: number[] = [];
73	  if (item.cursed) surcharges.push(base * CURSE_SURCHARGE);
74	  if (isHighEnchantment(item)) surcharges.push(base * HIGH_ENCHANTMENT_SURCHARGE);
75	  return { base, surcharges };
76	};
77	
78	const componentUnit = (count: number): PricedUnit => ({
79	  base: componentGroupBase(count),
80	  surcharges: [],
81	});
82	
83	const pricedUnits = (items: Item[]): PricedUnit[] => {
84	  const mainUnits = items.filter((item) => !isComponent(item)).map(mainItemUnit);
85	
86	  const components = items.filter(isComponent);
87	  const componentUnits = [...countByType(components).values()].map(componentUnit);
88	
89	  return [...mainUnits, ...componentUnits];
90	};
91	
92	const unitTotal = (unit: PricedUnit): number =>
93	  unit.base +
94	  unit.base * FIRST_INSURANCE_SURCHARGE +
95	  unit.surcharges.reduce((sum, surcharge) => sum + surcharge, 0);
96	
97	const quotePremium = (items: Item[], customer: Customer): number => {
98	  const units = pricedUnits(items);
99	  const itemsTotal = units.reduce((sum, unit) => sum + unitTotal(unit), 0);
100	  const policyBase = units.reduce((sum, unit) => sum + unit.base, 0);
101	  const loyaltyDiscount =
102	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? policyBase * LOYALTY_DISCOUNT : 0;
103	  return Math.ceil(itemsTotal - loyaltyDiscount + PROCESSING_FEE);
104	};
105	
106	export const runScenario = (scenario: Scenario): ScenarioResult => {
107	  const results = scenario.steps.map((step) => ({
108	    premium: quotePremium(step.items, scenario.customer),
109	  }));
110	  return { results };
111	};
